// Official schemas captured from the public ComfyUI revision recorded in this fixture.
// RunComfy definitions are generated by the real node_input_types adapter, not handwritten.
const fixture = JSON.parse(readFileSync(new URL('./fixtures/recent-switch-schemas.json', import.meta.url)));
const defs = fixture.definitions;
const typeOf = spec => Array.isArray(spec[0]) ? 'COMBO' : spec[0];
const defaultOf = spec => spec[1]?.default ?? (typeOf(spec) === 'COMFY_DYNAMICCOMBO_V3' ? spec[1].options[0].key : Array.isArray(spec[0]) ? spec[0][0] : spec[1]?.options?.[0]) ?? ({ INT: 0, FLOAT: 0, STRING: '', BOOLEAN: false }[spec[0]]);
const clone = value => JSON.parse(JSON.stringify(value));
function makeNode(type, overrides = {}) {
  const definition = defs[type], values = { ...overrides };
  for (let depth = 0; depth < 4; depth++) for (const [name, spec] of Object.entries(activeInputs(definition, values))) if (!(name in values)) values[name] = defaultOf(spec);
  const widgets = [], inputs = [];
  for (const [name, spec] of Object.entries(activeInputs(definition, values))) {
    const kind = typeOf(spec);
    if (kind === 'COMFY_AUTOGROW_V3') continue;
    if (kind !== 'COMFY_DYNAMICCOMBO_V3') inputs.push({ name, type: kind, link: null });
    if (['INT', 'FLOAT', 'STRING', 'BOOLEAN', 'COMBO', 'COMFY_DYNAMICCOMBO_V3'].includes(kind) && !spec[1]?.forceInput) widgets.push({ name, type: kind, value: values[name] });
  }
  if (Object.values(activeInputs(definition, values)).some(spec => spec[1]?.control_after_generate && !spec[1]?.forceInput)) widgets.push({ name: 'control_after_generate', value: 'fixed' });
  return { type, id: 1, widgets, inputs, outputs: definition.output.map((type, index) => ({ type, name: definition.output_name?.[index], links: [] })),
    pos: [20, 30], size: [300, 250], properties: {}, flags: {}, mode: 0,
    serialize() { return clone({ type: this.type, id: this.id, pos: this.pos, size: this.size, properties: this.properties, widgets: this.widgets, inputs: this.inputs, outputs: this.outputs }); },
    connect(slot, target, targetSlot) { return this.graph.connect(this, slot, target, targetSlot); },
  };
}
function setup(source, values = {}, media = []) {
  const node = makeNode(source, values);
  const graph = { nodes: [node], links: {}, nextId: 10, before: 0, after: 0,
    getNodeById(id) { return this.nodes.find(n => n.id === id); }, getLink(id) { return this.links[id]; },
    serialize() { return { nodes: this.nodes.map(n => n.serialize()), links: clone(this.links) }; },
    connect(origin, slot, target, targetSlot) { const id = ++this.nextId, link = { id, origin_id: origin.id, origin_slot: slot, target_id: target.id, target_slot: targetSlot }; this.links[id] = link; origin.outputs[slot].links.push(id); target.inputs[targetSlot].link = id; return link; },
    add(n) { n.graph = this; this.nodes.push(n); },
    remove(n) { this.nodes = this.nodes.filter(other => other !== n); for (const [id, link] of Object.entries(this.links)) if (link.origin_id === n.id || link.target_id === n.id) delete this.links[id]; },
    beforeChange() { this.before++; }, afterChange() { this.after++; }, change() {},
  };
  node.graph = graph;
  for (const [name, type = 'IMAGE'] of media) {
    const origin = { id: ++graph.nextId, type: 'FixtureSource', outputs: [{ type, links: [] }], serialize() { return { id: this.id, type: this.type }; }, connect: node.connect, graph };
    graph.nodes.push(origin);
    let index = node.inputs.findIndex(i => i.name === name);
    if (index < 0) { index = node.inputs.length; node.inputs.push({ name, type, link: null }); }
    graph.connect(origin, 0, node, index);
  }
  return { node, graph };
}

