for (const [source, target, values = {}, media = []] of positive) test(`recent official schema preserves ${source} → ${target}`, () => {
  const { node, graph } = setup(source, values, media), before = graph.serialize();
  assert(switchTargets(node, defs).includes(target));
  const plan = planSwitch(node, target, defs);
  assert.deepEqual(plan.errors, [], plan.errors.join('\n'));
  assert.deepEqual(graph.serialize(), before, 'preview must not mutate a graph');
  assert(plan.notes.some(n => n.includes('Explicit model/settings choice')));
  const replacement = applySwitch(plan, { definitions: defs, createNode: makeNode });
  assert.equal(replacement.type, target);
  assert.equal(graph.before, 1); assert.equal(graph.after, 1);
  for (const [sourceName] of media) assert(replacement.inputs.some(i => i.name === plan.inputMap[sourceName] && i.link != null), sourceName);
});

test('every new target belongs to a family menu or an explicit no-counterpart list', () => {
  const covered = new Set(['RunComfyNanoBanana2LiteT2I', 'RunComfyNanoBanana2LiteEdit']);
  for (const type of Object.keys(RECENT_SOURCES)) {
    assert(defs[type], `Missing real schema: ${type}`);
    for (const inputs of [[], [{ name: 'image', link: 1 }, { name: 'start_frame', link: 2 }]]) for (const target of recentSwitchTargets({ type, inputs }, defs)) covered.add(target);
  }
  assert.deepEqual(Object.keys(MODELS).filter(id => !covered.has(id)).sort(), ['RunComfyACEStep15T2A', 'RunComfyACEStepAudioInpaint', 'RunComfyACEStepAudioOutpaint', 'RunComfyACEStepT2A', 'RunComfyElevenLabsMusic'].sort());
  assert(recentSwitchTargets({ type: 'OpenAIGPTImageNodeV2', inputs: [] }, defs).every(id => id.startsWith('RunComfyGPTImage')));
  assert.deepEqual(recentSwitchTargets({ type: 'ThirdPartyKlingNode', inputs: [] }, defs), []);
});

