for (const [source, target, values, media, message] of blocked) test(`blocks unsafe ${source} → ${target}: ${message.source}`, () => {
  const { node, graph } = setup(source, values, media), before = graph.serialize();
  assert(switchTargets(node, defs).includes(target), 'recognized unsupported source still has a visible preview');
  const plan = planSwitch(node, target, defs);
  assert(plan.errors.some(error => message.test(error)), plan.errors.join('\n'));
  assert.throws(() => applySwitch(plan, { definitions: defs, createNode: makeNode }));
  assert.deepEqual(graph.serialize(), before);
});

test('new required media groups and linked secondary outputs block before mutation', () => {
  const { node, graph } = setup('HappyHorseReferenceVideoApi');
  assert(planSwitch(node, 'RunComfyHappyHorse11Reference', defs).errors.some(e => e.includes('required reference input')));
  const { node: omni } = setup('GeminiVideoOmniV2', { model: 'Omni Flash', 'model.task_type': 'text_to_video' });
  omni.outputs[1].links = [123];
  assert(planSwitch(omni, 'RunComfyGeminiOmniFlashT2V', defs).errors.some(e => e.includes('Connected output')));
  assert.equal(graph.before, 0);
  const { node: reference } = setup('KlingOmniProImageToVideoNode');
  assert(planSwitch(reference, 'RunComfyKlingO3ProReference', defs).errors.some(e => e.includes('at least one supported media reference')));
});

test('Seed Audio rate conversions are finite, bounded FLOAT values; linked rates cannot be converted', () => {
  for (const value of [NaN, Infinity, -Infinity]) {
    const { node } = setup('ByteDanceSeedAudio', { model: 'seed-audio-1.0', speech_rate: value });
    assert(planSwitch(node, 'RunComfySeedAudio10T2A', defs).errors.some(e => e.includes('speed must be a finite number')));
  }
  const { node } = setup('ByteDanceSeedAudio', { model: 'seed-audio-1.0' }, [['speech_rate', 'INT']]);
  assert(planSwitch(node, 'RunComfySeedAudio10T2A', defs).errors.some(e => e.includes('value conversion')));
});

test('connection-only seeds preserve upstream rerun control without requiring an absent target widget', () => {
  const { node } = setup('Wan3ReferenceToVideoApi', { 'model.duration': '5', 'model.ratio': '16:9' }, [['seed', 'INT']]);
  node.widgets.find(w => w.name === 'control_after_generate').value = 'randomize';
  const plan = planSwitch(node, 'RunComfyWan30T2V', defs);
  assert.deepEqual(plan.errors, []);
  assert.equal(plan.controlAfterGenerate, undefined);
  assert(plan.notes.some(n => n.includes('upstream node controls')));
  const replacement = applySwitch(plan, { definitions: defs, createNode: makeNode });
  assert(!replacement.widgets.some(w => w.name === 'control_after_generate'));
  assert(replacement.inputs.some(i => i.name === 'seed' && i.link != null));
});

test('every family candidate can apply with its native target layout or explains its incompatibility before mutation', () => {
  const seen = new Set();
  for (const source of Object.keys(RECENT_SOURCES)) {
    const sample = positive.find(row => row[0] === source);
    const values = sample?.[2] || {}, media = sample?.[3] || [];
    const { node } = setup(source, values, media);
    for (const target of recentSwitchTargets(node, defs)) {
      const { node: freshNode, graph } = setup(source, values, media), before = graph.serialize();
      const plan = planSwitch(freshNode, target, defs);
      seen.add(target);
      if (plan.errors.length) {
        assert(plan.errors.every(message => typeof message === 'string' && message.length > 20));
        assert.throws(() => applySwitch(plan, { definitions: defs, createNode: makeNode }));
        assert.deepEqual(graph.serialize(), before);
      } else assert.equal(applySwitch(plan, { definitions: defs, createNode: makeNode }).type, target, `${source} → ${target}`);
    }
  }
  assert(seen.size >= 105, `Only ${seen.size} target variants were exercised`);
});
